    clientID, err := ctx.GetClientIdentity().GetID()
    if err != nil {
        return fmt.Errorf("failed to get client identity: %v", err)
    }

    // Verify submitter is authorized to send from this account
    if !isAuthorized(ctx, clientID, from) {
        return fmt.Errorf("client %s not authorized to create payment from account %s", clientID, from)
    }

    // ... rest of function
}

func (p *PaymentContract) RefundPayment(ctx contractapi.TransactionContextInterface, paymentID string) error {
    // Add authorization check
    clientID, err := ctx.GetClientIdentity().GetID()
    if err != nil {
        return fmt.Errorf("failed to get client identity: %v", err)
    }

    // Only allow original recipient or admin to refund
    // ... rest of function
}
```

---

### 2. Insufficient Input Validation
**Severity:** High  
**Location:** `CreatePayment` function  
**Lines:** 44-72

**Description:**  
Multiple input validation issues exist:
- No validation of `id` parameter (could be empty, duplicate, or contain malicious characters)
- No validation of `from` and `to` addresses (could be empty, identical, or invalid)
- No length limits on string inputs (potential DoS via large inputs)
- Currency validation exists but happens after amount checks (inefficient)

**Recommended Fix:**
```go
func (p *PaymentContract) CreatePayment(ctx contractapi.TransactionContextInterface, id string, from string, to string, amount float64, currency string) error {
    // Validate ID
    if id == "" || len(id) > 64 {
        return fmt.Errorf("invalid payment ID: must be 1-64 characters")
    }

    // Check for duplicate ID
    existing, err := ctx.GetStub().GetState(id)
    if err != nil {
        return fmt.Errorf("failed to check existing payment: %v", err)
    }
    if existing != nil {
        return fmt.Errorf("payment with ID %s already exists", id)
    }

    // Validate addresses
    if from == "" || to == "" {
        return fmt.Errorf("from and to addresses cannot be empty")
    }
    if from == to {
        return fmt.Errorf("cannot transfer to same account")
    }
    if len(from) > 128 || len(to) > 128 {
        return fmt.Errorf("address length exceeds maximum")
    }

    // Validate currency first (fail fast)
    if !isCurrencySupported(currency) {
        return fmt.Errorf("currency %s is not supported", currency)
    }

    // Validate amount
    if amount <= 0 {
        return fmt.Errorf("amount must be positive")
    }
    if amount > maxTransferLimit {
        return fmt.Errorf("amount %.2f exceeds maximum transfer limit %.2f", amount, maxTransferLimit)
    }

    // ... rest of function
}
```

---

### 3. Floating-Point Precision Issues
**Severity:** Medium  
**Location:** Fee calculation and amount handling  
**Lines:** 66, 156-159

**Description:**  
Using `float64` for financial calculations can lead to:
- Precision loss in fee calculations
- Rounding errors accumulating over multiple transactions
- Potential for exploitation through carefully crafted amounts
- The `roundToDecimal` function mitigates but doesn't eliminate the issue

**Recommended Fix:**
```go
// Use integer representation (cents/smallest unit)
type Payment struct {
    ID       string  `json:"id"`
    From     string  `json:"from"`
    To       string  `json:"to"`
    Amount   int64   `json:"amount"`   // Amount in smallest currency unit (e.g., cents)
    Fee      int64   `json:"fee"`      // Fee in smallest currency unit
    Currency string  `json:"currency"`
    Status   string  `json:"status"`
}

func (p *PaymentContract) CreatePayment(ctx contractapi.TransactionContextInterface, id string, from string, to string, amount int64, currency string) error {
    if amount <= 0 {
        return fmt.Errorf("amount must be positive")
    }

    maxLimit := int64(maxTransferLimit * 100) // Convert to cents
    if amount > maxLimit {
        return fmt.Errorf("amount exceeds maximum transfer limit")
    }

    // Fee calculation with integer arithmetic
    fee := (amount * int64(feeRateBasisPts)) / 10000

    // ... rest of function
}
```

---

