**Recommended Fix:**
```go
func (v *VotingContract) CastVote(ctx contractapi.TransactionContextInterface, electionID string, voterID string, candidateID string) error {
    // Verify election exists and is open
    electionKey := "ELECTION_" + electionID
    electionJSON, err := ctx.GetStub().GetState(electionKey)
    if err != nil {
        return fmt.Errorf("failed to read election: %v", err)
    }
    if electionJSON == nil {
        return fmt.Errorf("election %s does not exist", electionID)
    }

    var election map[string]interface{}
    err = json.Unmarshal(electionJSON, &election)
    if err != nil {
        return err
    }

    status, ok := election["status"].(string)
    if !ok || status != "OPEN" {
        return fmt.Errorf("election %s is not open for voting", electionID)
    }

    // ... rest of function
}
```

