	// ... existing code ...

	// Check for duplicate votes
	for _, voter := range proposal.Voters {
		if voter == voterID {
			return fmt.Errorf("voter %s has already voted on proposal %s", voterID, proposalID)
		}
	}

	// ... rest of function
}
